176	/*
177	 * Virtual Memory Layout
178	 * 0x0_0000_1000 ~ 0x0_0001_0000: share
179	 * 0x0_0001_0000 ~ 0x0_0001_3000: code
180	 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
181	 */
182	PTE* init_page_table()
183	{
184	    PTE *pgdir = alloc_pgdir_page();
185	    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
186	    PTE *kernel_pgdir_kva = (PTE*)pa2kva(PGDIR_PA);
187	
188	    /* Every address space keeps the whole kernel half mapped: the direct
189	     * mapping of physical memory (VPN2 0x101) and the ioremap window
190	     * (VPN2 0x180) are shared, so kernel code -- including the device
191	     * interrupt handlers -- keeps working whoever is running. */
192	    for(int vpn2 = NUM_PTE_ENTRY / 2; vpn2 < NUM_PTE_ENTRY; vpn2++){
193	        pgdir_kva[vpn2] = kernel_pgdir_kva[vpn2];
194	    }
195	
196	    /* the program image and the first page of the user stack */
197	    for(uintptr_t va = USER_CODE_BEGIN; va < USER_CODE_END; va += PAGE_SIZE){
198	        alloc_page_helper(va, (uintptr_t)pgdir);
199	    }
200	    alloc_page_helper(USER_STACK_ADDR - PAGE_SIZE, (uintptr_t)pgdir);
201	
202	    return pgdir;
203	}
