205	void free_process_user_page(PTE* pgdir)
206	{
207	    if(pgdir == NULL || (uintptr_t)pgdir == PGDIR_PA){
208	        return;
209	    }
210	
211	    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
212	
213	    /* Only the user half is owned by this process; VPN2 >= 0x100 belongs to
214	     * the kernel, which is shared by everybody. */
215	    for(int vpn2 = 0; vpn2 < NUM_PTE_ENTRY / 2; vpn2++){
216	        if(!get_attribute(pgdir_kva[vpn2], _PAGE_PRESENT)){
217	            continue;
218	        }
219	        uintptr_t second_pa = get_pa(pgdir_kva[vpn2]);
220	        PTE *second_kva = (PTE*)pa2kva(second_pa);
221	
222	        for(int vpn1 = 0; vpn1 < NUM_PTE_ENTRY; vpn1++){
223	            if(!get_attribute(second_kva[vpn1], _PAGE_PRESENT)){
224	                continue;
225	            }
226	            uintptr_t third_pa = get_pa(second_kva[vpn1]);
227	            PTE *third_kva = (PTE*)pa2kva(third_pa);
228	
229	            for(int vpn0 = 0; vpn0 < NUM_PTE_ENTRY; vpn0++){
230	                PTE leaf = third_kva[vpn0];
231	                if(leaf == 0){
232	                    continue;
233	                }
234	                if(get_attribute(leaf, _PAGE_PRESENT)){
235	                    uintptr_t pa = get_pa(leaf);
236	                    int shared = 0;
237	                    /* a shared page only goes away with its last user */
238	                    for(int k = 0; k < SHM_PAGE_NUM; k++){
239	                        if(shm_page[k].count > 0 && shm_page[k].pa == pa){
240	                            shm_page[k].count--;
241	                            if(shm_page[k].count == 0){
242	                                free_user_page(pa);
243	                                shm_page[k].pa = 0;
244	                            }
245	                            shared = 1;
246	                            break;
247	                        }
248	                    }
249	                    if(!shared){
250	                        free_user_page(pa);
251	                    }
252	                }
253	                else if(get_attribute(leaf, _PAGE_SOFT)){
254	                    /* the page was swapped out, give the disk slot back */
255	                    disk_page[get_pfn(leaf)].valid = 0;
256	                }
257	                third_kva[vpn0] = 0;
258	            }
259	
260	            free_pgdir_page(third_pa);
261	            second_kva[vpn1] = 0;
262	        }
263	
264	        free_pgdir_page(second_pa);
265	        pgdir_kva[vpn2] = 0;
266	    }
267	
268	    free_pgdir_page((uintptr_t)pgdir);
269	    local_flush_tlb_all();
270	}
