272	/* Walk the three levels of `pgdir` (a pa) down to the leaf entry for `va`,
273	 * creating the intermediate tables on the way. Returns a pointer to the leaf
274	 * PTE, which the caller reaches through the kernel's direct mapping. */
275	static PTE* walk_pgdir(uintptr_t va, uintptr_t pgdir)
276	{
277	    uint64_t vpn[3];
278	    vpn[2] = (va >> VPN2_SHIFT) & VPN_MASK;
279	    vpn[1] = (va >> VPN1_SHIFT) & VPN_MASK;
280	    vpn[0] = (va >> VPN0_SHIFT) & VPN_MASK;
281	
282	    PTE *table = (PTE*)pa2kva(pgdir);
283	    for(int level = 2; level > 0; level--){
284	        PTE *entry = table + vpn[level];
285	        if(!get_attribute(*entry, _PAGE_PRESENT)){
286	            PTE *next = alloc_pgdir_page();
287	            *entry = 0;
288	            set_pfn(entry, (uintptr_t)next >> NORMAL_PAGE_SHIFT);
289	            /* a pointer entry carries no R/W/X bits */
290	            set_attribute(entry, _PAGE_PRESENT);
291	        }
292	        table = (PTE*)pa2kva(get_pa(*entry));
293	    }
294	    return table + vpn[0];
295	}
296	
297	/* Same walk, but without creating anything: returns NULL when the address is
298	 * not backed by a leaf entry at all. */
299	static PTE* find_pte(uintptr_t va, uintptr_t pgdir)
300	{
301	    uint64_t vpn[3];
302	    vpn[2] = (va >> VPN2_SHIFT) & VPN_MASK;
303	    vpn[1] = (va >> VPN1_SHIFT) & VPN_MASK;
304	    vpn[0] = (va >> VPN0_SHIFT) & VPN_MASK;
305	
306	    PTE *table = (PTE*)pa2kva(pgdir);
307	    for(int level = 2; level > 0; level--){
308	        PTE *entry = table + vpn[level];
309	        if(!get_attribute(*entry, _PAGE_PRESENT)){
310	            return NULL;
311	        }
312	        table = (PTE*)pa2kva(get_pa(*entry));
313	    }
314	    return table + vpn[0];
315	}
