317	/*
318	 * Make sure `va` is backed by a physical frame in `pgdir` (a pa) and return
319	 * the kernel virtual address of that frame.  A page that had been swapped out
320	 * is read back from the SD card first.  The signature matches the callback
321	 * load_elf() expects, so it doubles as the "prepare page" hook of do_exec().
322	 */
323	// pgdir is pa. if va is not mapped, then mapped it
324	uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir)
325	{
326	    va = ROUNDDOWN(va, PAGE_SIZE);
327	    PTE *pte = walk_pgdir(va, pgdir);
328	
329	    if(!get_attribute(*pte, _PAGE_PRESENT)){
330	        if(get_attribute(*pte, _PAGE_SOFT)){
331	            /* the page lives in the swap area, fetch it back */
332	            uint64_t slot = get_pfn(*pte);
333	            uintptr_t pa = alloc_user_page(0, pte);
334	            sbi_sd_read((unsigned int)pa, PAGE_SD_BLOCKS, SWAP_BEGIN + slot * PAGE_SD_BLOCKS);
335	            disk_page[slot].valid = 0;
336	            *pte = 0;
337	            set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
338	        }
339	        else{
340	            uintptr_t pa = alloc_user_page(0, pte);
341	            *pte = 0;
342	            set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
343	        }
344	        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE | _PAGE_EXEC |
345	                           _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
346	        local_flush_tlb_all();
347	    }
348	
349	    return pa2kva(get_pa(*pte));
350	}
