352	uintptr_t shm_page_get(int key)
353	{
354	    shm_page_t *page = &shm_page[(uint32_t)key % SHM_PAGE_NUM];
355	
356	    if(page->count == 0){
357	        /* first user of this key: give the group a pinned frame, it must
358	         * never be swapped out behind the back of the other sharers */
359	        page->pa = alloc_user_page(1, NULL);
360	    }
361	
362	    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
363	    for(uintptr_t va = SHM_VA_BEGIN; va < SHM_VA_END; va += PAGE_SIZE){
364	        PTE *pte = walk_pgdir(va, pgdir);
365	        if(get_attribute(*pte, _PAGE_PRESENT) || get_attribute(*pte, _PAGE_SOFT)){
366	            continue;
367	        }
368	        *pte = 0;
369	        set_pfn(pte, page->pa >> NORMAL_PAGE_SHIFT);
370	        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
371	                           _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
372	        page->count++;
373	        local_flush_tlb_all();
374	        return va;
375	    }
376	
377	    /* the share window of this process is full */
378	    if(page->count == 0){
379	        free_user_page(page->pa);
380	        page->pa = 0;
381	    }
382	    return 0;
383	}
