385	void shm_page_dt(uintptr_t addr)
386	{
387	    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
388	    PTE *pte = find_pte(ROUNDDOWN(addr, PAGE_SIZE), pgdir);
389	
390	    if(pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)){
391	        return;
392	    }
393	
394	    /* only a page that really belongs to a share group may be detached,
395	     * otherwise a bogus address would silently unmap private memory */
396	    uintptr_t pa = get_pa(*pte);
397	    for(int i = 0; i < SHM_PAGE_NUM; i++){
398	        if(shm_page[i].count > 0 && shm_page[i].pa == pa){
399	            *pte = 0;
400	            local_flush_tlb_all();
401	
402	            shm_page[i].count--;
403	            if(shm_page[i].count == 0){
404	                free_user_page(pa);
405	                shm_page[i].pa = 0;
406	            }
407	            return;
408	        }
409	    }
410	}
