412	void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
413	{
414	    /* Anything outside the user half of the Sv39 address space is a genuine
415	     * kernel bug; let the generic handler dump the context. */
416	    if(stval >= (1lu << (VPN2_SHIFT + PPN_BITS - 1))){
417	        handle_other(regs, stval, cause);
418	        return;
419	    }
420	
421	    /* demand paging: give the faulting address a frame (or fetch it back
422	     * from the swap area) and let the instruction run again */
423	    alloc_page_helper(stval, (uintptr_t)current_running[cpu_id]->pgdir);
424	}

